Claro a continuación te comparto un ejemplo en donde he utilizado un array de cadenas para almacenar el dibujo del ahorcado, y lo he ido actualizando según el número de intentos fallidos. En la parte comentada del código, se podrían añadir la lógica necesaria para leer la letra introducida por el jugador desde la consola, comprobar si está en la palabra a adivinar, y comprobar si el jugador ha adivinado la palabra o ha perdido el juego.

public class Ahorcado {
    public static void main(String[] args) {
        int intentos = 0; // Número de intentos fallidos
        int maxIntentos = 6; // Número máximo de intentos permitidos
        boolean ahorcado = false; // Indica si el jugador ha perdido

        // Dibujo del ahorcado
        String[] dibujo = {"  +---+",
                           "  |   |",
                           "      |",
                           "      |",
                           "      |",
                           "      |",
                           "========="};

        // Bucle principal
        while (!ahorcado) {
            // Imprime el dibujo actual
            for (int i = 0; i < dibujo.length; i++) {
                System.out.println(dibujo[i]);
            }

            // Pide una letra al jugador (aquí se podría añadir la lógica para leer la letra desde la consola)
            char letra = 'a';

            // Comprueba si la letra está en la palabra a adivinar (aquí se podría añadir la lógica para comprobar si la letra está en la palabra)
            boolean acierto = false;

            if (!acierto) {
                intentos++;
            }

            // Actualiza el dibujo según el número de intentos fallidos
            switch (intentos) {
                case 1:
                    dibujo[2] = "  O   |";
                    break;
                case 2:
                    dibujo[3] = "  |   |";
                    break;
                case 3:
                    dibujo[3] = " \\|   |";
                    break;
                case 4:
                    dibujo[3] = " \\|/  |";
                    break;
                case 5:
                    dibujo[4] = " /    |";
                    break;
                case 6:
                    dibujo[4] = " / \\  |";
                    ahorcado = true;
                    break;
            }

            // Comprueba si el jugador ha perdido
            if (ahorcado) {
                // Imprime el dibujo final
                for (int i = 0; i < dibujo.length; i++) {
                    System.out.println(dibujo[i]);
                }
                System.out.println("Has perdido.");
            } else {
                // Comprueba si el jugador ha adivinado la palabra (aquí se podría añadir la lógica para comprobar si el jugador ha ganado)
                if (true) {
                    System.out.println("Has ganado.");
                    ahorcado = true;
                }
            }
        }
    }
}

